Cristian's Algorithm is a clock synchronization algorithm is used to synchronize time with a time server by client processes. This algorithm works well with low-latency networks where Round Trip Time is short as compared to accuracy while redundancy-prone distributed systems/applications do not go hand in hand with this algorithm. Here Round Trip Time refers to the time duration between the start of a Request and the end of the corresponding Response.Below is an illustration imitating the working of Cristian's algorithm:  Algorithm:1) The process on the client machine sends the request for fetching clock time(time at the server) to the Clock Server at time T_0 .2) The Clock Server listens to the request made by the client process and returns the response in form of clock server time.3) The client process fetches the response from the Clock Server at time T_1 and calculates the synchronized client clock time using the formula given below.T_{CLIENT} = T_{SERVER} + \frac{(T_1 - T_0)}{2} where T_{CLIENT} refers to the synchronized clock time, T_{SERVER} refers to the clock time returned by the server, T_0 refers to the time at which request was sent by the client process, T_1 refers to the time at which response was received by the client processWorking/Reliability of the above formula:T_1 - T_0 refers to the combined time taken by the network and the server to transfer the request to the server, process the request, and return the response back to the client process, assuming that the network latency T_0 and T_1 are approximately equal.The time at the client-side differs from actual time by at most \frac{(T_1 - T_0)}{2} seconds. Using the above statement we can draw a conclusion that the error in synchronization can be at most \frac{(T_1 - T_0)}{2} seconds. Hence,  error\, \epsilon\, [-\frac{(T_1 - T_0)}{2} , \, \frac{(T_1 - T_0)}{2} ]  Python Codes below illustrate the working of Cristian's algorithm: Code below is used to initiate a prototype of a clock server on local machine: 
            C++

    // C++ equivalent 
#include <iostream>
#include <string>
#include <chrono>
#include <ctime>
#include <sys/socket.h>

// Function used to initiate the Clock Server
void initiateClockServer() {
    // Create socket
    int socketfd = socket(AF_INET, SOCK_STREAM, 0);
    std::cout << "Socket successfully created" << std::endl;

    // Set port
    int port = 8000;

    // Bind socket to port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(port);
    bind(socketfd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    std::cout << "Socket is listening..." << std::endl;

    // Start listening to requests
    listen(socketfd, 5);

    // Clock Server Running forever
    while (true) {
        // Establish connection with client
        struct sockaddr_in client_addr;
        int client_len = sizeof(client_addr);
        int connfd = accept(socketfd, (struct sockaddr*) &client_addr, (socklen_t*)&client_len);
        std::cout << "Server connected to " << client_addr.sin_addr.s_addr << std::endl;

        // Respond the client with server clock time
        std::chrono::time_point<std::chrono::system_clock> now = std::chrono::system_clock::now();
        std::time_t time = std::chrono::system_clock::to_time_t(now);
        std::string time_str = std::ctime(&time);
        send(connfd, time_str.c_str(), time_str.size(), 0);

        // Close the connection with the client process 
        close(connfd);
    }
}

// Driver function
int main() {
    // Trigger the Clock Server
    initiateClockServer();
    return 0;
}


            Java

    import java.net.*;
import java.io.*;
import java.util.Date;

public class ClockServer {
    // Function used to initiate the Clock Server
    public static void initiateClockServer() throws IOException 
    {

        // Create socket
        ServerSocket serverSocket = new ServerSocket(8000);
        System.out.println("Socket successfully created");

        // Clock Server Running forever
        while (true)
        {

            // Start listening to requests
            System.out.println("Socket is listening...");
            Socket clientSocket = serverSocket.accept();
            System.out.println("Server connected to " + clientSocket.getInetAddress());

            // Respond the client with server clock time
            Date now = new Date();
            String timeStr = now.toString();
            OutputStream os = clientSocket.getOutputStream();
            OutputStreamWriter osw = new OutputStreamWriter(os);
            BufferedWriter bw = new BufferedWriter(osw);
            bw.write(timeStr + "\n");
            bw.flush();

            // Close the connection with the client process
            clientSocket.close();
        }
    }

    // Driver function
    public static void main(String[] args) throws IOException
    {

        // Trigger the Clock Server
        initiateClockServer();
    }
}


